<script setup>
import {ref,onMounted} from 'vue'
import TreatmentInvoice from './TreatmentInvoice.vue'
import InvoiceSettlement from './InvoiceSettlement.vue'
const items=ref([]),unbilled=ref([]),status=ref('PENDING'),cursor=ref(''),unbilledCursor=ref(''),detail=ref(null),generate=ref(null),settling=ref(false),busy=ref(false),notice=ref('')
async function request(path){const r=await fetch('/api/v1/staff/billing/'+path,{cache:'no-store',redirect:'error',signal:AbortSignal.timeout(12000)});if(r.status!==200)throw Error();return r.json()}
async function load(after=''){if(busy.value)return;busy.value=true;notice.value='';try{const d=await request('invoices?'+new URLSearchParams({status:status.value,cursor:after||'0'}));items.value=after?[...items.value,...d.items]:d.items;cursor.value=d.nextCursor||''}catch{notice.value='无法读取账单，请核对登录与权限。'}finally{busy.value=false}}
async function loadUnbilled(after=''){if(busy.value)return;busy.value=true;notice.value='';try{const d=await request('unbilled-visits?cursor='+(after||'0'));unbilled.value=after?[...unbilled.value,...d.items]:d.items;unbilledCursor.value=d.nextCursor||''}catch{notice.value='无法读取待出账就诊。'}finally{busy.value=false}}
async function open(row){if(busy.value)return;busy.value=true;detail.value=null;settling.value=false;notice.value='';try{const d=await request('invoices/'+row.invoiceId);if(d.invoiceId!==row.invoiceId)throw Error();detail.value=d;generate.value=null}catch{notice.value='详情暂不可用，请刷新账单。'}finally{busy.value=false}}
onMounted(()=>load())
</script>
<template><section><h1>账单与结算</h1><div class="toolbar"><label>账单状态<select v-model="status" :disabled="busy" @change="load()"><option value="PENDING">待处理</option><option value="">全部</option><option>待核对确认</option><option>待结算</option><option>已结算</option><option>待再次确认</option><option>待核实</option></select></label><button :disabled="busy" @click="load()">刷新账单</button><button :disabled="busy" @click="loadUnbilled()">查看待出账就诊</button></div><p role="status">{{notice}}</p>
<div class="billing-table-scroll"><table><thead><tr><th>患者</th><th>就诊</th><th>账单 / 版本</th><th>金额（元）</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in items" :key="row.invoiceId"><td>{{row.patientId}}</td><td>{{row.visitId}}</td><td>{{row.invoiceId}} / {{row.invoiceVersionNo}}</td><td>{{row.total}}</td><td>{{row.status}}</td><td><button :disabled="busy" @click="open(row)">查看详情</button></td></tr></tbody></table></div><p v-if="!busy&&!items.length">当前条件下暂无账单。</p><button v-if="cursor" :disabled="busy" @click="load(cursor)">加载更多账单</button>
<section v-if="unbilled.length"><h2>待出账就诊</h2><p v-for="row in unbilled" :key="row.visitId">患者{{row.patientId}} · 就诊{{row.visitId}} <button @click="generate=row;detail=null">生成或查看账单</button></p><button v-if="unbilledCursor" :disabled="busy" @click="loadUnbilled(unbilledCursor)">加载更多就诊</button></section>
<TreatmentInvoice v-if="generate" :key="generate.visitId" :initial="generate" />
<section v-if="detail"><h2>账单{{detail.invoiceId}} · 版本{{detail.invoiceVersionNo}}</h2><p>就诊{{detail.visitId}} · {{detail.status}}</p><div class="billing-table-scroll"><table><thead><tr><th>项目</th><th>数量</th><th>单价（元）</th><th>金额（元）</th></tr></thead><tbody><tr v-for="line in detail.lines" :key="line.clinicalRecordId"><td>{{line.item}}</td><td>{{line.quantity}} {{line.unit}}</td><td>{{line.unitPrice}}</td><td>{{line.amount}}</td></tr></tbody></table></div><p><strong>合计{{detail.total}}元</strong></p><button :disabled="busy" @click="open(detail)">刷新详情</button><button v-if="!settling&&detail.status!=='已结算'" @click="settling=true">核对无误，进入模拟结算</button><InvoiceSettlement v-if="settling" :key="detail.invoiceId+'-'+detail.invoiceVersionNo" :initial="detail" /></section>
</section></template>
<style scoped>section{display:grid;gap:1rem}.toolbar{display:flex;gap:1rem;flex-wrap:wrap}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:.75rem;border-bottom:1px solid #ccd9d4}button{justify-self:start}.billing-table-scroll{width:100%;max-width:100%;min-width:0;overflow-x:auto}.billing-table-scroll table{min-width:560px}.billing-table-scroll td button{white-space:nowrap}section{min-width:0}
</style>
